def frequency_report(symbols, k):
    if type(k) is not int or k < 0:
        raise ValueError("expected nonnegative integer k")
    counts = {}
    for symbol in symbols:
        if type(symbol) is not str or not symbol or not symbol.isascii() or not symbol.isalnum():
            raise ValueError("expected nonempty ASCII letters/digits")
        counts[symbol] = counts.get(symbol, 0) + 1
    ordered = sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))
    return ordered[:k]

print(frequency_report(["B", "A", "B", "A", "a"], 3))
print(frequency_report([], 2))

def has_pair_sum(values, target):
    # Precondition: ascending integer sequence and integer target.
    left, right = 0, len(values) - 1
    while left < right:
        total = values[left] + values[right]
        if total == target:
            return True
        if total < target:
            left += 1
        else:
            right -= 1
    return False

print(has_pair_sum([1, 2, 4, 7], 9))
print(has_pair_sum([1, 2, 4, 7], 8))
print(has_pair_sum([4], 8))
print(has_pair_sum([4, 4], 8))

