def run_cache(capacity, ops):
    cache = OrderedDict()
    lines = []
    for operation in ops:
        (kind, key) = operation[:2]
        if kind == 'GET':
            if key not in cache:
                lines.append('MISS')
            else:
                lines.append(str(cache[key]))
                cache.move_to_end(key)
        else:
            value = int(operation[2])
            cache[key] = value
            cache.move_to_end(key)
            if len(cache) > capacity:
                cache.popitem(last=False)
    return lines

ops = [['PUT', 'A', '1'], ['PUT', 'B', '2'], ['GET', 'A'], ['PUT', 'C', '3'], ['GET', 'B'], ['PUT', 'A', '4'], ['GET', 'A']]
print(*run_cache(2, ops), sep='\n')
